/**
 * @method
 * @name scwin.digitalChangePage
 * @author Inswave
 * @date 2026. 09. 29
 * @param tab
 * @returns
 * @hidden N
*/
scwin.digitalChangePage = async function (tab) {
    /* sdd-asis-lifecycle:begin fn_DigitalChangePage — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.digitalListForm || { elements: [] });
    const lastSaveStatCdInt = parseInt($c.util.getComponent('dma_DigitalChangePageReq').get('lastSaveStatCd'));
    if (tab == 1) {
        return;
    } else {
        if (tab == 2) {
            $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewIsurTab');
        } else {
            if (tab == 3) {
                $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewSrtyLpTab');
            } else {
                $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewAttachFileTab');
            }
        }
    }
    scwin.form.action = 'DigitalList.do';
    await scwin.tx_fn_DigitalChangePage();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.digitalListForm || { elements: [] });
    scwin.form.action = "DigitalList.do";
    $c.util.getComponent('dma_DigitalChangePageReq').set('listBzTpCd', "");
    $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'searchList');
    await scwin.tx_fn_Search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.distrPayBas
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.distrPayBas = function () {
    /* sdd-asis-lifecycle:begin fn_distrPayBas — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    for (let i = 1; i <= 12; i++) {
        if (i == 1) {
            var mmdd = $c.util.getComponent('ipt_distrPayBasDd').getValue();
            var mm = mmdd.substring(0, 2);
            var dd = mmdd.substring(2, 4);
            void("mmdd==" + mmdd + "mm==" + mm + "dd==" + dd);
            $c.util.getComponent('slc_distrPayBasM').setValue(mm).prop("selected", true);
            $c.util.getComponent('slc_distrPayBasD').setValue(dd).prop("selected", true);
        } else {
            void(i);
            var mmdd = $("input[name='distrPayBasDd" + i + "']").val();
            var mm = mmdd.substring(0, 2);
            var dd = mmdd.substring(2, 4);
            $("select[name='distrPayBasM" + i + "']").val(mm).prop("selected", true);
            $("select[name='distrPayBasD" + i + "']").val(dd).prop("selected", true);
        }
    }
    /* sdd-asis-lifecycle:end */
};


