/**
 * @method
 * @name scwin.insertComma
 * @author Inswave
 * @date 2026. 09. 29
 * @param tab
 * @returns
 * @hidden N
*/
scwin.insertComma = function (tab) {
    /* sdd-asis-lifecycle:begin fn_insertComma — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    scwin.form = (document.digitalListForm || { elements: [] });
    const elem = scwin.form.elements;

    if(tab == 1) {
        for(var i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('listQty') >= 0 ||
                elem[i].name.indexOf('pubofrAmt') >= 0 ||
                elem[i].name.indexOf('listAmt') >= 0 ||
                elem[i].name.indexOf('addIsuPrc') >= 0 ||
                elem[i].name.indexOf('addListRnd') >= 0 ||					
                elem[i].name.indexOf('dutyHdCnt') >= 0 
            ) 

            fn_ObjValueSetComma(elem[i]);			
        }
    } else if(tab == 2) {
        for(var i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('totAsstAmt') >= 0 || 
                elem[i].name.indexOf('totAsstAmt2') >= 0 ||
                elem[i].name.indexOf('totAsstAmt3') >= 0 ||
                elem[i].name.indexOf('totDebtAmt') >= 0 ||
                elem[i].name.indexOf('totDebtAmt2') >= 0 ||
                elem[i].name.indexOf('totDebtAmt3') >= 0 ||
                elem[i].name.indexOf('totCap') >= 0 ||
                elem[i].name.indexOf('totCap2') >= 0 ||					
                elem[i].name.indexOf('totCap3') >= 0 ||
                elem[i].name.indexOf('cap') >= 0 ||
                elem[i].name.indexOf('cap2') >= 0 ||
                elem[i].name.indexOf('cap3') >= 0 ||
                elem[i].name.indexOf('sales') >= 0 ||
                elem[i].name.indexOf('sales2') >= 0 ||
                elem[i].name.indexOf('sales3') >= 0 ||
                elem[i].name.indexOf('contbzProftAmt') >= 0 ||
                elem[i].name.indexOf('contbzProftAmt2') >= 0 ||
                elem[i].name.indexOf('contbzProftAmt3') >= 0 ||
                elem[i].name.indexOf('netincmAmt') >= 0 ||
                elem[i].name.indexOf('netincmAmt2') >= 0 ||
                elem[i].name.indexOf('netincmAmt3') >= 0 
            ) {
                if(elem[i].name==='capInroadYns') 
                {

                }else{
                    fn_ObjValueSetComma(elem[i]);
                }
            } 

        }
    } else if(tab == 3) {
        for(var i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('totAsstAmt') >= 0 || 
                elem[i].name.indexOf('totDebtAmt') >= 0 ||
                elem[i].name.indexOf('totCap') >= 0 ||
                elem[i].name.indexOf('cap') >= 0 ||
                elem[i].name.indexOf('bzProftAmt') >= 0 ||
                elem[i].name.indexOf('ordnincmAmt') >= 0 ||
                elem[i].name.indexOf('netincmAmt') >= 0 ||
                elem[i].name.indexOf('bzActivCashFlowAmt') >= 0 ||				
                elem[i].name.indexOf('basEqtycap') >= 0 ||
                elem[i].name.indexOf('riskAsstVal') >= 0 ||
                elem[i].name.indexOf('etnSrtyPrincCapRto') >= 0 ||
                elem[i].name.indexOf('srtyEqtycap') >= 0 ||
                elem[i].name.indexOf('srtyIsuTotamt') >= 0 ||
                elem[i].name.indexOf('srtyMiscIsuAmt') >= 0 ||
                elem[i].name.indexOf('srtyIsuLimit') >= 0 ||				
                elem[i].name.indexOf('lpFbzNetcap') >= 0 ||
                elem[i].name.indexOf('lpTotRiskAmt') >= 0 ||
                elem[i].name.indexOf('lpReqPersisPrincCapVal') >= 0 ||
                elem[i].name.indexOf('lpNcr') >= 0
            ) fn_ObjValueSetComma(elem[i]);
        }		
    } else if(tab == 4) {

    }
    /* sdd-asis-lifecycle:end */
};
